      - ./database/init:/docker-entrypoint-initdb.d:ro
    healthcheck:
      test: [CMD-SHELL, "pg_isready -U dracula_owner -d dracula_food"]
      interval: 5s
      timeout: 5s
      retries: 20
  migrate:
    build: ./backend
    restart: "no"
    depends_on:
      db: {condition: service_healthy}
    environment:
      <<: *app-env
      SUPERUSER_DATABASE_URL: postgresql+psycopg://dracula_owner:${POSTGRES_PASSWORD}@db:5432/dracula_food
    volumes:
      - ./database:/app/database:ro
      - ./data:/app/data
    command: [sh, -c, "python -m database.migrations.apply && python seed_dracula.py"]
