    build: ./backend
    restart: unless-stopped
    depends_on:
      migrate: {condition: service_completed_successfully}
    environment: *app-env
    volumes:
      - ./data:/app/data
    healthcheck:
      test: [CMD-SHELL, "python -c \"import urllib.request; urllib.request.urlopen('http://127.0.0.1:4120/health')\""]
      interval: 15s
      timeout: 5s
      retries: 6
      start_period: 20s
    command: [gunicorn, --workers=2, --threads=4, --timeout=120, --bind=0.0.0.0:4120, --access-logfile=-, "app.dracula:create_app()"]
  admin:
    build: ./frontend
    restart: unless-stopped
    depends_on:
      backend: {condition: service_healthy}
    ports:
      - "${BIND_ADDRESS:-127.0.0.1}:${SHOP_PORT:-4183}:80"
