                    product = _resolve(repo, item)
                    if product:
                        repo.set_qty(cart_id, str(product["id"]),
                                     int(item.get("qty") or 1),
                                     float(product["price_ron"] or 0),
                                     offer=product.get("offer"))
        else:
            ref = {"product_id": product_ref} if product_ref else body
            product = _resolve(repo, {**body, **ref})
            if product is None:
                return _error("unknown_product", 404)
            pid = str(product["id"])
            price = float(product["price_ron"] or 0)
            # `price_ron` din `resolve_product` e deja preÈ›ul cu oferta automatÄƒ
            if action == "add":
                repo.add(cart_id, pid, int(body.get("qty") or 1), price,
                         offer=product.get("offer"))
            elif action == "set":
                repo.set_qty(cart_id, pid, int(body.get("qty") or 0), price,
                             offer=product.get("offer"))
            elif action == "remove":
                repo.remove(cart_id, pid)

        payload = _cart_payload(ctx, cart_id, locale)
    finally:
        _close_ctx(scope)
    return _with_cart_cookie(make_response(jsonify(payload), 200), token)


def _resolve(repo: CartRepo, data: dict[str, Any]) -> dict[str, Any] | None:
    """AcceptÄƒ `product_id` (uuid), `id` (`wp-<n>`, cum trimite JS-ul azi) sau `sku`."""
    raw = str(data.get("product_id") or "").strip()
    external = str(data.get("external_id") or data.get("id") or "").strip()
    sku = str(data.get("sku") or "").strip()
    if raw and "-" in raw and len(raw) == 36:
        product = repo.resolve_product(product_id=raw)
        if product:
            return product
    if raw and not external:
        external = raw
    return repo.resolve_product(external_id=external or None, sku=sku or None)


