async function start(){try{const verificationUrl=new URL(location.href);const verificationToken=verificationUrl.pathname.endsWith('/account')?verificationUrl.searchParams.get('verify'):null;if(verificationToken){verificationUrl.searchParams.delete('verify');history.replaceState({},'',verificationUrl.pathname+verificationUrl.search+verificationUrl.hash);}const segment=location.pathname.split('/')[1];if(/^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$/.test(segment))state.locale=segment;state.data=await api(bootstrapPath());state.locale=state.data.locale;await refresh();await render();if(verificationToken){try{await api('/api/account/verify-email','POST',{token:verificationToken});await refresh();await render();toast(state.data.ui['auth.verified']);}catch(error){toast(errorMessage(error));}}}catch(e){app.innerHTML='<div class="empty"><h1>Dracula Food</h1><p role="alert">'+esc(e.message)+'</p><button onclick="location.reload()">â†»</button></div>';}}
start();
